head.b:skin:
:root{
  --bg:#05070d;
  --bg-soft:#0a0f1c;
  --surface:rgba(255,255,255,0.045);
  --surface-strong:rgba(255,255,255,0.08);
  --border:rgba(255,255,255,0.10);
  --border-strong:rgba(96,165,250,0.45);
  --blue-300:#93c5fd;
  --blue-400:#60a5fa;
  --blue-500:#3b82f6;
  --blue-600:#2563eb;
  --indigo-500:#6366f1;
  --text:#eef1fb;
  --text-soft:#93a0bd;
  --text-dim:#5b6785;
  --amber:#fbbf24;
  --radius:18px;
  --font-heading:'Space Grotesk', 'Inter', sans-serif;
  --font-body:'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --mono:ui-monospace, SFMono-Regular, Consolas, 'Liberation Mono', monospace;
  --max-w:1120px;
  --nav-h:72px;
}
*{box-sizing:border-box;}
html{scroll-behavior:smooth;}
body{
  margin:0;
  background:
    radial-gradient(ellipse 900px 560px at 12% -8%, rgba(59,130,246,0.28), transparent 60%),
    radial-gradient(ellipse 800px 520px at 105% 8%, rgba(99,102,241,0.20), transparent 60%),
    radial-gradient(ellipse 700px 500px at 50% 100%, rgba(59,130,246,0.10), transparent 60%),
    var(--bg);
  color:var(--text);
  font-family:var(--font-body);
  line-height:1.6;
  -webkit-font-smoothing:antialiased;
}
*{scroll-margin-top:calc(var(--nav-h) + 14px);}
img,svg{max-width:100%; display:block;}
a{color:inherit; text-decoration:none;}
ul{margin:0; padding:0; list-style:none;}
h1,h2,h3,h4{font-family:var(--font-heading); margin:0;}

/* ---- Announcement bar ---- */
.announce{
  background:linear-gradient(90deg, rgba(251,191,36,0.14), rgba(251,191,36,0.08));
  border-bottom:1px solid rgba(251,191,36,0.25);
  color:#fcd34d;
  font-size:13px;
  font-weight:600;
  text-align:center;
  padding:9px 16px;
}
.announce strong{color:#fde68a;}

/* ---- Navbar ---- */
.navbar{
  position:sticky; top:0; z-index:100;
  height:var(--nav-h);
  display:flex; align-items:center;
  background:rgba(5,7,13,0.75);
  backdrop-filter:blur(14px); -webkit-backdrop-filter:blur(14px);
  border-bottom:1px solid var(--border);
}
.nav-inner{
  max-width:var(--max-w); width:100%; margin:0 auto;
  padding:0 24px;
  display:flex; align-items:center; justify-content:space-between; gap:20px;
}
.brand{display:flex; align-items:center; gap:10px; font-family:var(--font-heading); font-weight:700; font-size:17px; color:var(--text);}
.brand-mark{
  width:34px; height:34px; border-radius:10px; flex-shrink:0;
  background:linear-gradient(135deg, var(--blue-400), var(--indigo-500));
  display:flex; align-items:center; justify-content:center;
  font-family:var(--font-heading); font-weight:700; color:#04060c; font-size:16px;
  box-shadow:0 0 22px -4px rgba(96,165,250,0.7);
}
.nav-toggle-input{display:none;}
.nav-links{
  display:flex; align-items:center; gap:30px;
  font-size:14px; font-weight:600;
}
.nav-links a{color:var(--text-soft); transition:color .15s ease;}
.nav-links a:hover{color:var(--text);}
.nav-right{display:flex; align-items:center; gap:14px;}
.nav-toggle{display:none; flex-direction:column; gap:5px; cursor:pointer; padding:8px;}
.nav-toggle span{width:22px; height:2px; border-radius:2px; background:var(--text);}

/* ---- Buttons ---- */
.btn{
  display:inline-flex; align-items:center; justify-content:center; gap:8px;
  padding:13px 26px; border-radius:12px;
  font-family:var(--font-body); font-weight:700; font-size:14.5px;
  border:1px solid transparent; cursor:pointer; white-space:nowrap;
  transition:transform .15s ease, filter .15s ease, background .15s ease;
}
.btn-primary{
  background:linear-gradient(135deg, var(--blue-500), var(--indigo-500));
  color:#fff;
  box-shadow:0 10px 30px -10px rgba(59,130,246,0.65);
}
.btn-primary:hover{filter:brightness(1.1); transform:translateY(-1px);}
.btn-outline{background:transparent; border-color:var(--border-strong); color:var(--text);}
.btn-outline:hover{background:var(--surface);}
.btn-sm{padding:9px 18px; font-size:13px; border-radius:10px;}

/* ---- Hero ---- */
.hero{
  position:relative;
  padding:96px 24px 88px;
  text-align:center;
  background-image:
    linear-gradient(rgba(255,255,255,0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.05) 1px, transparent 1px);
  background-size:44px 44px;
  -webkit-mask-image:radial-gradient(ellipse 70% 100% at 50% 0%, #000 40%, transparent 100%);
          mask-image:radial-gradient(ellipse 70% 100% at 50% 0%, #000 40%, transparent 100%);
}
.hero-inner{
  -webkit-mask-image:none; mask-image:none;
  max-width:760px; margin:0 auto;
}
.badge{
  display:inline-flex; align-items:center; gap:8px;
  padding:7px 16px; border-radius:999px;
  background:var(--surface); border:1px solid var(--border-strong);
  font-size:13px; font-weight:700; letter-spacing:0.02em; color:var(--blue-300);
  margin-bottom:26px; font-family:var(--mono);
}
.badge .dot{width:7px; height:7px; border-radius:50%; background:var(--blue-400); box-shadow:0 0 10px 2px var(--blue-400);}
.hero h1{
  font-size:clamp(34px,6.2vw,60px); font-weight:700; line-height:1.08;
  letter-spacing:-0.02em; margin-bottom:20px;
  background:linear-gradient(135deg, #ffffff 20%, var(--blue-300) 100%);
  -webkit-background-clip:text; background-clip:text; color:transparent;
}
.hero .lead{
  max-width:600px; margin:0 auto 38px; color:var(--text-soft); font-size:17px;
}
.hero .lead em{color:var(--text-dim); font-style:italic;}
.hero-ctas{display:flex; gap:14px; justify-content:center; flex-wrap:wrap; margin-bottom:52px;}
.stat-pills{display:flex; flex-wrap:wrap; justify-content:center; gap:10px;}
.stat-pill{
  background:var(--surface); border:1px solid var(--border); border-radius:12px;
  padding:11px 18px; text-align:left; min-width:118px;
}
.stat-pill .k{display:block; font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:0.06em; color:var(--text-dim); margin-bottom:3px;}
.stat-pill .v{display:block; font-family:var(--mono); font-weight:600; font-size:15px; color:var(--text);}

/* ---- Sections ---- */
.section{padding:88px 24px;}
.section-alt{background:linear-gradient(180deg, transparent, rgba(255,255,255,0.02), transparent);}
.section-inner{max-width:var(--max-w); margin:0 auto;}
.eyebrow{
  display:inline-block; color:var(--blue-400); font-weight:700; font-size:12.5px;
  letter-spacing:0.10em; text-transform:uppercase; margin-bottom:12px;
}
.section-title{font-size:clamp(26px,4vw,36px); font-weight:700; letter-spacing:-0.01em; margin-bottom:16px;}
.section-desc{color:var(--text-soft); max-width:600px; font-size:16px; margin-bottom:48px;}
.section-desc em{color:var(--text-dim);}

/* ---- Glass card ---- */
.card{
  background:var(--surface); border:1px solid var(--border); border-radius:var(--radius);
  padding:26px; transition:border-color .2s ease, transform .2s ease;
}
.card:hover{border-color:var(--border-strong);}

/* ---- About ---- */
.about-grid{display:grid; grid-template-columns:1.1fr 0.9fr; gap:48px; align-items:start;}
.checklist{display:flex; flex-direction:column; gap:10px; margin-top:24px;}
.checklist li{
  display:flex; gap:10px; align-items:flex-start; font-size:14.5px; color:var(--text-soft);
  background:var(--surface); border:1px solid var(--border); border-radius:12px; padding:12px 14px;
}
.checklist .ic{color:var(--blue-400); flex-shrink:0; margin-top:1px;}
.about-stats{display:grid; grid-template-columns:1fr 1fr; gap:14px;}
.icon-tile{
  width:44px; height:44px; border-radius:12px;
  background:linear-gradient(135deg, rgba(96,165,250,0.22), rgba(99,102,241,0.16));
  border:1px solid var(--border-strong);
  display:flex; align-items:center; justify-content:center; color:var(--blue-300);
  margin-bottom:14px;
}

/* ---- Tokenomics ---- */
.tokenomics-grid{display:grid; grid-template-columns:auto 1fr; gap:56px; align-items:center;}
.donut-wrap{position:relative; width:224px; height:224px; margin:0 auto;}
.donut{width:100%; height:100%; border-radius:50%;
  background:conic-gradient(var(--blue-500) 0% 40%, var(--indigo-500) 40% 65%, var(--blue-300) 65% 85%, rgba(255,255,255,0.14) 85% 100%);
  box-shadow:0 0 60px -12px rgba(59,130,246,0.5);
}
.donut-center{
  position:absolute; inset:20%; border-radius:50%;
  background:var(--bg-soft); border:1px solid var(--border);
  display:flex; flex-direction:column; align-items:center; justify-content:center;
}
.donut-center .t1{font-family:var(--font-heading); font-weight:700; font-size:18px;}
.donut-center .t2{font-size:11px; color:var(--text-dim); text-transform:uppercase; letter-spacing:0.06em;}
.legend{display:flex; flex-direction:column; gap:10px; margin-bottom:28px;}
.legend-item{
  display:flex; align-items:center; justify-content:space-between; gap:12px;
  padding:13px 16px; background:var(--surface); border:1px solid var(--border); border-radius:12px; font-size:14.5px;
}
.legend-item .l{display:flex; align-items:center; gap:10px; color:var(--text-soft); font-weight:600;}
.legend-dot{width:10px; height:10px; border-radius:3px; flex-shrink:0;}
.legend-item .v{font-family:var(--mono); font-weight:700; color:var(--text);}
.detail-list{border:1px solid var(--border); border-radius:14px; overflow:hidden;}
.detail-row{
  display:flex; justify-content:space-between; gap:16px; padding:14px 18px;
  border-bottom:1px solid var(--border); font-size:14px;
}
.detail-row:last-child{border-bottom:none;}
.detail-row .label{color:var(--text-soft); font-weight:600; flex-shrink:0;}
.detail-row .value{font-family:var(--mono); color:var(--text); text-align:right; word-break:break-all;}

/* ---- Utility grid ---- */
.grid-auto{display:grid; grid-template-columns:repeat(auto-fit, minmax(230px,1fr)); gap:18px;}
.feature-title{font-family:var(--font-heading); font-weight:600; font-size:17px; margin-bottom:8px;}
.feature-desc{color:var(--text-soft); font-size:14.5px;}

/* ---- Roadmap ---- */
.timeline{position:relative; display:flex; flex-direction:column; gap:34px;}
.timeline::before{
  content:''; position:absolute; left:15px; top:6px; bottom:6px; width:2px;
  background:linear-gradient(var(--blue-500), var(--indigo-500));
  opacity:0.4;
}
.timeline-item{position:relative; padding-left:48px;}
.timeline-dot{
  position:absolute; left:5px; top:2px; width:22px; height:22px; border-radius:50%;
  background:var(--bg-soft); border:2px solid var(--blue-400);
  box-shadow:0 0 14px 1px rgba(96,165,250,0.6);
}
.timeline-item .phase{font-family:var(--mono); font-size:12.5px; font-weight:700; color:var(--blue-400); text-transform:uppercase; letter-spacing:0.06em; margin-bottom:6px;}
.timeline-item h3{font-size:18px; font-weight:600; margin-bottom:6px;}
.timeline-item p{color:var(--text-soft); font-size:14.5px; margin:0;}

/* ---- How to buy ---- */
.steps-grid{display:grid; grid-template-columns:repeat(auto-fit, minmax(220px,1fr)); gap:18px; margin-bottom:36px;}
.step-num{
  width:36px; height:36px; border-radius:10px; display:flex; align-items:center; justify-content:center;
  background:linear-gradient(135deg, var(--blue-500), var(--indigo-500)); color:#fff;
  font-family:var(--font-heading); font-weight:700; font-size:15px; margin-bottom:16px;
}
.buy-ctas{display:flex; gap:14px; flex-wrap:wrap;}

/* ---- FAQ ---- */
.faq-list{display:flex; flex-direction:column; gap:12px;}
.faq-item{background:var(--surface); border:1px solid var(--border); border-radius:14px; padding:4px 20px; overflow:hidden;}
.faq-item summary{
  list-style:none; cursor:pointer; padding:16px 0;
  display:flex; align-items:center; justify-content:space-between; gap:16px;
  font-weight:600; font-size:15.5px; color:var(--text);
}
.faq-item summary::-webkit-details-marker{display:none;}
.faq-item summary::after{
  content:'+'; font-size:22px; font-weight:400; color:var(--blue-400); flex-shrink:0;
  transition:transform .2s ease;
}
.faq-item[open] summary::after{transform:rotate(45deg);}
.faq-item p{color:var(--text-soft); font-size:14.5px; margin:0 0 18px; padding-top:2px;}

/* ---- Disclaimer ---- */
.notice{
  border-radius:16px; padding:22px 24px; font-size:14.5px; line-height:1.65;
}
.notice-amber{background:rgba(251,191,36,0.08); border:1px solid rgba(251,191,36,0.3); color:#fde68a;}
.notice-amber strong{color:#fcd34d;}
.notice + .notice{margin-top:16px;}

/* ---- Footer ---- */
.site-footer{border-top:1px solid var(--border); padding:48px 24px 32px;}
.footer-inner{max-width:var(--max-w); margin:0 auto; display:flex; flex-wrap:wrap; justify-content:space-between; align-items:center; gap:20px;}
.footer-links{display:flex; gap:22px; font-size:13.5px; font-weight:600; color:var(--text-soft);}
.footer-links a:hover{color:var(--text);}
.footer-copy{color:var(--text-dim); font-size:13px; width:100%; margin-top:24px; text-align:center;}

/* ---- Responsive ---- */
@media (max-width:900px){
  .about-grid{grid-template-columns:1fr; gap:32px;}
  .tokenomics-grid{grid-template-columns:1fr; gap:36px; text-align:center;}
  .donut-wrap{margin:0 auto;}
  .legend{text-align:left;}
}
@media (max-width:860px){
  .nav-links{
    position:fixed; inset:var(--nav-h) 0 0 0; z-index:99;
    background:rgba(5,7,13,0.97); backdrop-filter:blur(14px);
    flex-direction:column; align-items:flex-start; gap:4px;
    padding:20px; border-top:1px solid var(--border);
    transform:translateY(-10px); opacity:0; pointer-events:none;
    transition:opacity .2s ease, transform .2s ease;
  }
  .nav-links a{width:100%; padding:14px 6px; border-bottom:1px solid var(--border); font-size:16px;}
  .nav-toggle-input:checked ~ .nav-links{opacity:1; transform:translateY(0); pointer-events:auto;}
  .nav-toggle{display:flex;}
}
@media (max-width:640px){
  .hero{padding:64px 20px 56px;}
  .section{padding:64px 20px;}
  .section-desc{margin-bottom:32px;}
  .nav-right .btn-sm{padding:8px 14px; font-size:12.5px;}
  .detail-row{flex-direction:column; gap:4px;}
  .detail-row .value{text-align:left;}
}
